arguments.script:
// Attack 1: a builder's Released: lands between a claim run's read and its writes. The next run must read the claim
// run's own label events as its own and open the issue again, or the release is lost.
import { readFileSync } from "node:fs";

const workflow = readFileSync(".github/workflows/claim.yml", "utf8").split("\n");
const start = workflow.findIndex((line) => /^\s*script: \|\s*$/.test(line));
const indent = (line) => line.length - line.trimStart().length;
const body = [];
for (const line of workflow.slice(start + 1)) {
	if (line.trim() !== "" && indent(line) <= indent(workflow[start])) break;
	body.push(line);
}
const depth = Math.min(...body.filter((line) => line.trim() !== "").map(indent));
const script = body.map((line) => line.slice(depth)).join("\n");

const bot = "github-actions[bot]";
const label = (name, actor, event) => ({ event, label: { name }, actor: { login: actor } });
const release = { id: 3, event: "commented", body: "Released: done", user: { login: "builder" }, html_url: "https://x/3" };
const timeline = [
	label("status: ready", "maintainer", "labeled"),
	{ id: 2, event: "commented", body: "Claim: builder", user: { login: "builder" }, html_url: "https://x/2" },
	release,
	// The claim run's writes, after the release it never read.
	label("status: in progress", bot, "labeled"),
	label("status: ready", bot, "unlabeled"),
];
let labels = ["status: in progress"];
const github = {
	paginate: async () => timeline,
	rest: {
		issues: {
			get: async () => ({ data: { state: "open", labels: labels.map((name) => ({ name })) } }),
			listEventsForTimeline: () => undefined,
			getComment: async () => ({ data: release }),
			addLabels: async ({ labels: added }) => {
				labels = [...new Set([...labels, ...added])];
			},
			removeLabel: async ({ name }) => {
				labels = labels.filter((each) => each !== name);
			},
		},
		repos: {
			getCollaboratorPermissionLevel: async ({ username }) => ({
				data: { permission: username === "maintainer" ? "admin" : "write", role_name: "write" },
			}),
		},
	},
};
const context = { repo: { owner: "o", repo: "r" }, payload: { comment: release, issue: { number: 1 } } };
const core = { info: (message) => console.log(`info: ${message}`) };
await new (Object.getPrototypeOf(async () => {}).constructor)("github", "context", "core", script)(github, context, core);
console.log(`labels after the release's run: ${JSON.stringify(labels)}`);
process.exit(labels.includes("status: ready") && !labels.includes("status: in progress") ? 0 : 1);
